import {
  array,
  createTypeContext,
  declare,
  docComment,
  object,
  type JsonSchema,
  typeDeclaration,
} from "./render-defs.js";

const header = `// Generated by tooling/generate-types from definitions/api.schema.json.
// Do not edit by hand.
`;

const runtimeRef = "runtime.schema.json#/$defs/";
const compositionRef = "composition.schema.json";
const compositionType = "LumenComposition";

/** A union that also takes any other string, because another host can send values of its own. */
function openUnion(name: string, def: JsonSchema, values: readonly unknown[]): string {
  const union = values.map((value) => `  | ${JSON.stringify(value)}`).join("\n");
  return `${docComment(def.description, "")}export type ${name} =\n${union}\n  | (string & {});`;
}

/** \`ErrorCode\` as an open union, and the table of the listed codes with their descriptions. */
function renderErrorCode(name: string, def: JsonSchema): string {
  const codes = array(def["x-lumen-codes"]).map(object);
  if (codes.length === 0) throw new Error(`\`${name}\` lists no codes`);
  return `${openUnion(
    name,
    def,
    codes.map((entry) => entry.code),
  )}

/** Each error code lumen-server sends, with what it means. */
export const errorCodes = [
${codes.map((entry) => `  { code: ${JSON.stringify(entry.code)}, description: ${JSON.stringify(entry.description)} },`).join("\n")}
] as const;`;
}

/** The content type and file extension of each output format. */
function renderOutputFiles(def: JsonSchema): string {
  const files = array(def["x-lumen-files"]).map(object);
  if (files.length === 0) throw new Error("`OutputFormat` lists no files");
  const entries = files
    .map(
      (file) =>
        `  ${JSON.stringify(file.format)}: { contentType: ${JSON.stringify(file.contentType)}, extension: ${JSON.stringify(file.extension)} },`,
    )
    .join("\n");
  return `/** What a render of each output format downloads as: its content type and file extension. */
export const outputFiles = {
${entries}
} as const satisfies Readonly<Record<OutputFormat, { readonly contentType: string; readonly extension: string }>>;`;
}

/** The values a string union lists, from an \`enum\` or a \`oneOf\` of constants. */
function unionValues(def: JsonSchema): readonly unknown[] {
  if (Array.isArray(def.enum)) return def.enum;
  return array(def.oneOf).map((branch) => {
    const value = object(branch).const;
    if (value === undefined) throw new Error(`an open union has a branch that is not a constant`);
    return value;
  });
}

/**
 * The contents of `generated/api.ts`: the types of lumen-server's HTTP API. Values the engine
 * produces are the runtime types, and a request's composition is \`LumenComposition\`.
 */
export function renderApiTypes(schema: JsonSchema, runtimeSchema: JsonSchema): string {
  const defs = object(schema.$defs) as Record<string, JsonSchema>;
  const runtimeNames = Object.keys(object(runtimeSchema.$defs));
  const context = createTypeContext(
    defs,
    [
      ...runtimeNames.map((name): [string, string] => [`${runtimeRef}${name}`, name]),
      [compositionRef, compositionType],
    ],
    true,
  );
  const constants: string[] = [];
  for (const [name, def] of Object.entries(defs)) {
    if (def["x-lumen-codes"] !== undefined) {
      declare(context, name, renderErrorCode(name, def));
    } else if (def["x-lumen-open"] === true) {
      declare(context, name, openUnion(name, def, unionValues(def)));
    } else {
      declare(context, name, typeDeclaration(name, def, context, true));
    }
    if (def["x-lumen-files"] !== undefined) constants.push(renderOutputFiles(def));
  }

  const runtimeImports = runtimeNames.filter((name) => context.used.has(name)).sort();
  const imports = [
    ...(context.used.has(compositionType)
      ? [`import type { ${compositionType} } from "./schema.js";`]
      : []),
    ...(runtimeImports.length > 0
      ? [`import type { ${runtimeImports.join(", ")} } from "./runtime.js";`]
      : []),
  ];
  return `${header}
${imports.join("\n")}

${[...context.declarations.values(), ...constants].join("\n\n")}
`;
}
